    from collections import Counter

    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    edge = max((x for x in counts if x != bg), key=lambda x: counts[x])
    out = [row[:] for row in grid]

    bars = []
    for c, x in enumerate(grid[0]):
        if x == edge:
            bars.append((0, c, "up"))
    for c, x in enumerate(grid[-1]):
        if x == edge:
            bars.append((h - 1, c, "down"))
    for r in range(h):
        if grid[r][0] == edge:
            bars.append((r, 0, "left"))
        if grid[r][-1] == edge:
            bars.append((r, w - 1, "right"))

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == edge:
                continue
            # Select the nearest colored border bar and project toward it.
            choices = [(abs(r-br) + abs(c-bc), br, bc, direction)
                       for br, bc, direction in bars]
            _, br, bc, direction = min(choices)
            out[r][c] = 4
            if direction == "up":
                cells = ((rr, c) for rr in range(r-1, -1, -1))
            elif direction == "down":
                cells = ((rr, c) for rr in range(r+1, h))
            elif direction == "left":
                cells = ((r, cc) for cc in range(c-1, -1, -1))
            else:
                cells = ((r, cc) for cc in range(c+1, w))
            for rr, cc in cells:
                if grid[rr][cc] == edge:
                    break
                if grid[rr][cc] == bg:
                    out[rr][cc] = color
    return out
